head.script:
//
/* Exact OpiumBest polyfill */
(function(){
  var XHTML_NS="http://www.w3.org/1999/xhtml";
  var root=document.querySelector("foreignObject").firstElementChild;
  var originalCreateElement=document.createElement.bind(document);
  var originalCreateElementNS=document.createElementNS.bind(document);
  Object.defineProperty(document,"head",{get:function(){return root.querySelector("head");},configurable:true});
  Object.defineProperty(document,"body",{get:function(){return root.querySelector("body");},configurable:true});
  Object.defineProperty(document,"documentElement",{get:function(){return root;},configurable:true});
  document.createElement=function(tagName,options){
    if(typeof tagName==="string")return originalCreateElementNS(XHTML_NS,tagName,options);
    return originalCreateElement(tagName,options);
  };
  document.createElementNS=function(namespaceURI,qualifiedName,options){
    if(namespaceURI==null||namespaceURI===XHTML_NS)return originalCreateElementNS(XHTML_NS,qualifiedName,options);
    return originalCreateElementNS(namespaceURI,qualifiedName,options);
  };
})();
//

        //

(function(){
  var mirrors=[
    "https://cdn.jsdelivr.net/gh/TongSherbet/storage/",
    "https://fastly.jsdelivr.net/gh/TongSherbet/storage/",
    "https://gcore.jsdelivr.net/gh/TongSherbet/storage/",
    "https://quantil.jsdelivr.net/gh/TongSherbet/storage/",
    "https://testingcf.jsdelivr.net/gh/TongSherbet/storage/",
    "https://jsdelivr.b-cdn.net/gh/TongSherbet/storage/",
    "https://cdn.statically.io/gh/TongSherbet/storage@main/",
    "https://raw.githubusercontent.com/TongSherbet/storage/main/"
  ];
  var hour=Math.floor(Date.now()/3600000);
  // CRITICAL: SW must be same host as this page (cdn vs fastly)
  try {
    var repoSw = location.origin + location.pathname.replace(/[^/]+$/, "") + "sw.js";
    if (/jsdelivr|b-cdn\.net/i.test(location.hostname) && location.pathname.indexOf("/gh/") >= 0) {
      window.swPath = repoSw;
    } else if (/jsdelivr|b-cdn\.net/i.test(location.hostname)) {
      window.swPath = location.origin + "/gh/Mo9nikeypurple/skool/sw.js";
    } else {
      window.swPath = repoSw;
    }
  } catch (e) {
    window.swPath = "sw.js";
  }
  console.log("[opium-boot] swPath=", window.swPath, "location=", location.href);
  (async function(){
    for (var i = 0; i < mirrors.length; i++) {
      try {
        var res = await fetch(mirrors[i] + "loader.js?" + hour + "&raw", { cache: "no-store", signal: AbortSignal.timeout(8000) });
        if (!res.ok) continue;
        var txt = await res.text();
        if (!txt || txt.length < 500 || !/function|serviceWorker/.test(txt)) continue;
        window.assetsBase = mirrors[i];
        var s = document.createElement("script");
        s.textContent = txt;
        document.head.appendChild(s);
        return;
      } catch (e) {}
    }
    console.warn("[opium-boot] loader.js not found — Mac OS SW will register alone");
  })();
})();

        //

//
(async function () {
  // NO BLOB. Inject Mac OS into this SVG document (Opium pattern).
  function status(t) {
    var el = document.getElementById("status");
    if (el) el.textContent = t;
    try { console.log("[svg]", t); } catch (e) {}
  }

  // Force SW path on THIS origin only (fixes cdn vs fastly error)
  try {
    var dir = location.pathname.replace(/[^/]+$/, "");
    if (/\/gh\//.test(dir)) {
      window.swPath = location.origin + dir + "sw.js";
    } else {
      window.swPath = location.origin + "/gh/Mo9nikeypurple/skool/sw.js";
    }
    console.log("[svg] locked swPath", window.swPath);
  } catch (e) {}

  var pageUrl = new URL("index.html", location.href).href;
  var baseHref = new URL("./", location.href).href;
  status("Loading Mac OS into SVG (no blob)…");

  var html;
  try {
    var res = await fetch(pageUrl, { cache: "no-store", mode: "cors" });
    if (!res.ok) throw new Error("HTTP " + res.status);
    html = await res.text();
  } catch (e) {
    status("Fetch failed: " + e.message + " @ " + pageUrl);
    return;
  }

  // Inject parent + swPath so Mac OS never invents fastly URL
  var sw = String(window.swPath || "").replace(/\\/g, "\\\\").replace(/"/g, '\\"');
  var parent = String(location.href).replace(/\\/g, "\\\\").replace(/"/g, '\\"');
  html = html.replace(/<head[^>]*>/i, function (m) {
    return m +
      '<base href="' + baseHref + '">' +
      '<script>window.__NYX_SVG_PARENT="' + parent + '";window.swPath="' + sw + '";window.assetsBase=window.assetsBase||"https://cdn.jsdelivr.net/gh/TongSherbet/storage/";<\/script>';
  });

  var parsed = new DOMParser().parseFromString(html, "text/html");

  if (!document.querySelector("base")) {
    var b = document.createElement("base");
    b.href = baseHref;
    document.head.insertBefore(b, document.head.firstChild);
  }

  parsed.querySelectorAll("style, link[rel='stylesheet']").forEach(function (n) {
    try { document.head.appendChild(document.importNode(n, true)); } catch (e) {}
  });

  if (parsed.body) {
    document.body.innerHTML = "";
    Array.prototype.slice.call(parsed.body.childNodes).forEach(function (n) {
      try { document.body.appendChild(document.importNode(n, true)); } catch (e) {}
    });
  }

  var scripts = Array.prototype.slice.call(parsed.querySelectorAll("script"));
  status("Scripts 0/" + scripts.length);
  for (var i = 0; i < scripts.length; i++) {
    if (i % 20 === 0) status("Scripts " + i + "/" + scripts.length);
    var orig = scripts[i];
    await new Promise(function (resolve) {
      var done = false;
      function fin() { if (!done) { done = true; resolve(); } }
      try {
        var el = document.createElement("script");
        if (orig.src) {
          el.src = orig.src;
          el.async = false;
          el.onload = fin;
          el.onerror = fin;
          document.head.appendChild(el);
          setTimeout(fin, 2500);
        } else {
          el.textContent = orig.textContent || "";
          document.head.appendChild(el);
          fin();
        }
      } catch (e) { fin(); }
    });
  }
  status("Ready");
  console.log("[svg] DONE location=", location.href, "swPath=", window.swPath);
})();
//
